mutations.content:
command /givepigaxe:
    permission: op
    trigger:
        give 1 of iron axe named "&dPig Axe" with lore "&7Striking a mob spawns a pig!" to player

on damage:
    if attacker is a player:
        if name of attacker's tool is "&dPig Axe":
            if victim is a living entity:
                if victim is not a player:
                    spawn 1 pig at victim
                    send "&dOink!" to attacker
